function storyReviewExcerpt(text){
 const clean=text.replace(/\s+/g,' ').trim();
 if(clean.length<=650&&clean.split(/\s+/).length<=100)return null;
 const opening=clean.slice(0,430),sentences=[...opening.matchAll(/[.!?](?:[”’"])?(?=\s|$)/g)];
 const boundary=sentences.filter(match=>match.index>=180).pop();
 return boundary?opening.slice(0,boundary.index+boundary[0].length):opening.slice(0,opening.lastIndexOf(' '))+'…';
}

