const customPicture=(stem,alt,priority=false)=>`<img src="assets/custom/${stem}-1280.webp" srcset="assets/custom/${stem}-640.webp 640w, assets/custom/${stem}-1280.webp 1280w" sizes="(max-width:700px) 92vw, 48vw" width="1280" height="1700" alt="${alt}" ${priority?'fetchpriority="high"':'loading="lazy"'}>`;

const escapeReview=value=>String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const privateReviews=['tp-1','tp-10','tp-private-ariana-bali'].map(id=>S.reviews.find(review=>review.id===id)).filter(Boolean);
const privateReviewBody=(review,index)=>{
 const full=`<div class="private-review-text">${review.fullText.split(/\n\n+/).map(paragraph=>`<p>${escapeReview(paragraph)}</p>`).join('')}</div>`;
 if(index===0)return full;
 const sentences=review.fullText.replace(/\n+/g,' ').match(/[^.!?]+[.!?]+(?:[”’"])?/g)||[review.fullText];
 const excerpt=sentences.slice(0,2).join('').trim();
 return `<div class="private-review-body"><p class="private-review-excerpt">${escapeReview(excerpt)}</p><div class="private-review-expanded" id="private-review-full-${review.id}" hidden>${full}</div></div>`;
};

const renderPrivateReviewCard=(review,i)=>`<article class="private-review-card ${i===0?'private-review-featured':''}" data-private-review="${review.id}"><div class="private-review-meta"><span>Private trip · Bali</span><span>Trustpilot ↗</span></div><div class="private-review-stars" aria-label="5 out of 5 stars">★★★★★</div>${i===0?`<div class="private-featured-author"><img src="assets/the-b-simone-portrait.webp" width="340" height="390" alt="The B Simone smiling on the beach" loading="lazy"><div><h3 class="private-review-name">${escapeReview(review.author)}</h3><h4>${escapeReview(review.title)}</h4></div></div>`:`<h3 class="private-review-name">${escapeReview(review.author)}</h3><h4>${escapeReview(review.title)}</h4>`}${privateReviewBody(review,i)}<div class="private-review-actions">${i>0?`<button type="button" class="private-review-toggle" data-private-review-toggle aria-expanded="false" aria-controls="private-review-full-${review.id}" aria-label="Read more of ${escapeReview(review.author)}’s review">Read more</button>`:''}<a class="text-link" href="${escapeReview(review.url)}" target="_blank" rel="noopener">${review.profileOnly?'View Trustpilot profile':'Read original on Trustpilot'} ↗</a></div></article>`;
const privateReviewSection=`<section class="private-trip-reviews section" id="private-trip-reviews" aria-labelledby="private-review-heading"><div class="section-head"><div><span class="eyebrow">Private trips. Personal experiences.</span><h2 id="private-review-heading">Their trip. <em>Their words.</em></h2></div><p>Three travelers on what it’s like to let T World Tours bring their private getaway to life.</p></div><div class="private-review-grid">${privateReviews.map(renderPrivateReviewCard).join('')}</div><a class="text-link private-more-stories" href="stories.html">Explore more traveler stories ↗</a></section>`;

const customPage=`<section class="custom-hero section"><div class="custom-hero-copy"><span class="eyebrow">Your occasion. Your people. Your itinerary.</span><h1><em>Custom</em><br>Private Trips</h1><p>Do you like one of our itineraries, but want to customize them to fit your private group? Contact us!</p><a href="#custom-occasions" class="btn">Find your kind of trip <span>↘</span></a><a class="text-link" href="#custom-inquiry">Already dreaming? Let’s talk ↗</a></div><div class="custom-hero-visual"><div class="custom-hero-photos"><div class="custom-hero-main">${customPicture('beach-dinner','A private dinner on the beach, surrounded by bright flowers and white drapes',true)}</div><div class="custom-hero-inset">${customPicture('ocean-couple','A couple enjoying the turquoise ocean together')}</div></div><p class="custom-photo-note">Your dream trip, done for you</p></div></section>
<section class="custom-occasions section" id="custom-occasions"><div class="section-head"><div><span class="eyebrow">There’s a trip for that</span><h2>Choose your<br><em>occasion</em></h2></div><p>Choose your occasion to explore the possibilities. We’ll make the itinerary your own.</p></div><div class="custom-explorer"><div class="custom-occasion-list" role="group" aria-label="Choose your custom trip type">${customOccasions.map((o,i)=>`<button type="button" data-custom-occasion="${i}" aria-pressed="${i===0}"><span class="custom-occasion-number">0${i+1}</span><span>${o.name.replace('/','/<wbr>')}</span><span class="custom-occasion-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><article class="custom-occasion-panel" aria-labelledby="custom-occasion-title"><div class="custom-occasion-image">${customPicture('beach-dinner',customOccasions[0].alt)}</div><div class="custom-occasion-copy" aria-live="polite"><span class="eyebrow" id="custom-occasion-name">Bachelor/Bachelorette</span><h3 id="custom-occasion-title">Your people. Your celebration.</h3><p id="custom-occasion-description">${customOccasions[0].text}</p><a href="#custom-inquiry" class="text-link" id="custom-plan-link">Plan this trip ↗</a></div></article></div></section>
<section class="custom-inquiry section" id="custom-inquiry"><div><span class="eyebrow">Let’s make it yours</span><h2>Tell us about<br><em>your dream trip</em></h2><p>Share more about your travel plans and start a custom trip inquiry.</p><a class="text-link" href="${C.call}" target="_blank" rel="noopener">Prefer to talk? Book a free call ↗</a><a class="custom-contact-email" href="mailto:${C.email}">${C.email}</a></div><form id="custom-trip-form"><div class="custom-form-grid"><label><span class="custom-field-label">First name <span aria-hidden="true">*</span></span><input name="name" autocomplete="given-name" required placeholder="Your first name" maxlength="150"></label><label><span class="custom-field-label">Email address <span aria-hidden="true">*</span></span><input name="email" type="email" autocomplete="email" required placeholder="you@example.com" maxlength="200"></label><label><span class="custom-field-label">Trip type <span aria-hidden="true">*</span></span><select name="occasion" required>${customOccasions.map(o=>`<option>${o.name}</option>`).join('')}</select></label><label><span class="custom-field-label">Dream destination (separate countries by commas) <span aria-hidden="true">*</span></span><input name="destination" required placeholder="Where would you love to go?" maxlength="200"></label></div><details class="custom-questionnaire" id="custom-questionnaire"><summary><span><span class="disclosure-closed">Read more</span><span class="disclosure-open">Show less</span><small>Complete the trip questionnaire</small></span><span class="disclosure-icon" aria-hidden="true">+</span></summary><div class="custom-questionnaire-content"><div class="custom-form-grid"><label><span class="custom-field-label">Approximate group size <span aria-hidden="true">*</span></span><input name="group" type="number" min="1" max="999" placeholder="How many travelers?" required></label><label><span class="custom-field-label">What is your budget per person, not including flights? (minimum $2,000) <span aria-hidden="true">*</span></span><input name="budget" type="number" min="2000" step="1" inputmode="numeric" required placeholder="e.g. 3000 (USD per person)"></label><label class="custom-form-wide"><span class="custom-field-label">What are your travel dates? Please specify approximately how many days/nights you want for your trip. <span aria-hidden="true">*</span></span><textarea name="dates" rows="2" required placeholder="Your preferred dates, how many days/nights, and whether you’re flexible" maxlength="500"></textarea></label><label class="custom-form-wide">Are there any specific activities you want us to include in your trip itinerary? (optional)<textarea name="activities" rows="3" placeholder="Tell us about your must-do experiences" maxlength="1000"></textarea></label><label><span class="custom-field-label">How did you hear about us? <span aria-hidden="true">*</span></span><select name="discovery" required><option value="" disabled selected>Select an option</option><option>Instagram</option><option>TikTok</option><option>Referral/word of mouth</option><option>YouTube</option><option>Google/web search</option><option>Other</option></select></label><label>What’s your or your brand’s social media handle so we can see your travel vibe? (optional)<input name="social" placeholder="@yourhandle and platform" maxlength="200"></label><label class="custom-form-wide">Are you celebrating a special occasion? If yes, mention the occasion below! (optional)<textarea name="celebration" rows="2" placeholder="A birthday, honeymoon, milestone, or something else worth celebrating…" maxlength="500"></textarea></label><label class="custom-form-wide">What would make this trip special? (optional)<span class="custom-field-help">Share a quick brain dump of what would make this your dream trip!</span><textarea name="details" rows="4" placeholder="Your vision, travel vibe, an itinerary you love, or anything else we should know…" maxlength="2000"></textarea></label></div><button class="btn" type="submit">Create my trip inquiry <span aria-hidden="true">✈️</span></button><p class="custom-form-note">This opens a prepared draft in your email app. Review it and press send to contact our team.</p><p id="custom-inquiry-status" role="status"></p></div></details></form></section>${privateReviewSection}<section class="custom-detail-strip section"><span class="eyebrow">A familiar itinerary. A personal touch.</span><h2>Keep what you love.<br><em>Make the rest your own.</em></h2><p>Start with a TWT itinerary that caught your eye, or tell us what you’re dreaming of. We’ll talk through the destination, your group, and the experiences you want to share.</p><div class="custom-detail-photos"><figure>${customPicture('egypt-couple','Two travelers walking hand in hand at the pyramids')}<figcaption>Time together</figcaption></figure><figure>${customPicture('egypt-group','T World Tours travelers at an Egyptian temple')}<figcaption>Shared discoveries</figcaption></figure><figure>${customPicture('island-culture','A traveler enjoying an island cultural experience')}<figcaption>Your own adventure</figcaption></figure></div></section>`;


