 const motion=document.querySelector('.process-motion-toggle');motion.onclick=()=>{const paused=motion.getAttribute('aria-pressed')!=='true';motion.setAttribute('aria-pressed',paused);motion.textContent=paused?'Resume motion ▶':'Pause motion Ⅱ';journey.classList.toggle('process-motion-paused',paused);map.querySelectorAll('svg').forEach(atlas=>{if(paused)atlas.pauseAnimations();else if(!reduced.matches)atlas.unpauseAnimations();});};
