if(!tours){
 const placeholder=document.querySelector('.newsletter-form'),slot=document.getElementById('twt-flodesk-inline');
 placeholder.addEventListener('submit',event=>{event.preventDefault();if(!placeholder.reportValidity())return;celebrateSignup(placeholder.querySelector('button[type=submit]'));document.getElementById('newsletter-status').textContent='Preview only: your details have not been submitted. Email signup and $50 code delivery will work once Flodesk is connected.';});
 const config=C.flodesk||{};
 async function appendEmbed(code,target){
  const template=document.createElement('template');template.innerHTML=code;
  const pending=[...template.content.querySelectorAll('script')];pending.forEach(script=>script.remove());target.append(template.content);
  for(const old of pending){const script=document.createElement('script');for(const attribute of old.attributes)script.setAttribute(attribute.name,attribute.value);script.textContent=old.textContent;
   if(old.src){await new Promise((resolve,reject)=>{script.onload=resolve;script.onerror=reject;target.append(script);});}else{target.append(script);}
  }
 }
 if(config.headerEmbed&&config.inlineEmbed){
  if(!window.TWT_FLODESK_READY)window.TWT_FLODESK_READY=appendEmbed(config.headerEmbed,document.head).catch(error=>{window.TWT_FLODESK_READY=null;throw error;});
  window.TWT_FLODESK_READY.then(async()=>{if(!slot.isConnected)return;slot.replaceChildren();await appendEmbed(config.inlineEmbed,slot);}).catch(()=>{if(!slot.isConnected)return;slot.replaceChildren(placeholder);placeholder.querySelector('.newsletter-status').textContent='The signup form couldn’t load. Please try again shortly.';});
 }
}

if(C.instagram?.feedEmbed){
 const feed=document.getElementById('instagram-feed');const fallback=feed.innerHTML;
 async function mountInstagramFeed(code){const template=document.createElement('template');template.innerHTML=code;const scripts=[...template.content.querySelectorAll('script')];scripts.forEach(script=>script.remove());feed.replaceChildren(template.content);for(const old of scripts){const script=document.createElement('script');for(const attr of old.attributes)script.setAttribute(attr.name,attr.value);script.textContent=old.textContent;if(old.src)await new Promise((resolve,reject)=>{script.onload=resolve;script.onerror=reject;feed.append(script);});else feed.append(script);}}
 mountInstagramFeed(C.instagram.feedEmbed).catch(()=>{if(feed.isConnected)feed.innerHTML=fallback;});
}

if(tours){
 const form=document.getElementById('destination-interest-form'),slot=document.getElementById('twt-destination-flodesk');
 form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;celebrateSignup(form.querySelector('button[type=submit]'));form.querySelector('.destination-interest-status').textContent='Preview only: your details have not been submitted. Destination signup and $50 code delivery will work once Flodesk is connected.';});
 const config=C.destinationFlodesk||{};
 if(config.headerEmbed&&config.inlineEmbed){
  async function insertDestinationEmbed(code,target){const template=document.createElement('template');template.innerHTML=code;const scripts=[...template.content.querySelectorAll('script')];scripts.forEach(script=>script.remove());target.append(template.content);for(const old of scripts){const script=document.createElement('script');for(const attr of old.attributes)script.setAttribute(attr.name,attr.value);script.textContent=old.textContent;if(old.src)await new Promise((resolve,reject)=>{script.onload=resolve;script.onerror=reject;target.append(script);});else target.append(script);}}
  if(!window.TWT_DESTINATION_FLODESK_READY)window.TWT_DESTINATION_FLODESK_READY=insertDestinationEmbed(config.headerEmbed,document.head).catch(error=>{window.TWT_DESTINATION_FLODESK_READY=null;throw error;});
  window.TWT_DESTINATION_FLODESK_READY.then(async()=>{if(!slot.isConnected)return;slot.replaceChildren();await insertDestinationEmbed(config.inlineEmbed,slot);}).catch(()=>{if(!slot.isConnected)return;slot.replaceChildren(form);form.querySelector('.destination-interest-status').textContent='The request form couldn’t load. Please try again shortly.';});
 }
}

if(tours&&C.toursRecap){
 const player=document.getElementById('egypt-recap');
 player.querySelector('button').addEventListener('click',()=>{
  const url=new URL(C.toursRecap),id=url.hostname==='youtu.be'?url.pathname.slice(1):url.searchParams.get('v');
  if(!/^[A-Za-z0-9_-]{11}$/.test(id||''))return;
  const frame=document.createElement('iframe');frame.title='T World Tours Egypt recap';
  frame.src='https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1&playsinline=1&rel=0';
  frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
  frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;
  document.querySelectorAll('video').forEach(video=>video.pause());player.replaceChildren(frame);
 });
 window.TWT_RECAP_CLEANUP=()=>player.replaceChildren();
}

if(custom){
 const form=document.getElementById('custom-trip-form');
 form.addEventListener('invalid',event=>{const disclosure=event.target.closest('details');if(disclosure)disclosure.open=true;},true);
 const image=document.querySelector('.custom-occasion-image img');
 function selectCustomOccasion(index){
  const o=customOccasions[index];
  document.querySelectorAll('[data-custom-occasion]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.customOccasion)===index)));
  image.src=`assets/custom/${o.image}-1280.webp`;
  image.srcset=`assets/custom/${o.image}-640.webp 640w, assets/custom/${o.image}-1280.webp 1280w`;
  image.alt=o.alt;
  document.getElementById('custom-occasion-name').textContent=o.name;
  document.getElementById('custom-occasion-title').textContent=o.line;
  document.getElementById('custom-occasion-description').textContent=o.text;
  document.getElementById('custom-plan-link').textContent='Plan this trip ↗';
  form.elements.occasion.value=o.name;
 }
 document.querySelectorAll('[data-custom-occasion]').forEach(b=>b.addEventListener('click',()=>selectCustomOccasion(Number(b.dataset.customOccasion))));
 form.elements.occasion.addEventListener('change',()=>selectCustomOccasion(form.elements.occasion.selectedIndex));
 form.addEventListener('submit',e=>{
  e.preventDefault();
  if(!form.reportValidity())return;
  const data=new FormData(form);
  const fields=[['First name','name'],['Email','email'],['Trip type','occasion'],['Destination','destination'],['Travelers','group'],['Budget per person (excluding flights)','budget'],['Travel dates and days/nights','dates'],['Specific activities','activities'],['How I heard about TWT','discovery'],['Social media handle','social'],['Special occasion','celebration'],['Dream trip brain dump','details']];
  const body='Hi T World Tours,\n\nI’d love to plan a private custom trip!\n\n'+fields.map(([label,key])=>label+': '+(data.get(key)||'To be discussed')).join('\n\n');
  const url='mailto:'+C.email+'?subject='+encodeURIComponent('Custom trip inquiry: '+data.get('occasion'))+'&body='+encodeURIComponent(body);
  const status=document.getElementById('custom-inquiry-status');status.replaceChildren();
  const msg=document.createElement('span');msg.textContent='Your inquiry is ready. Send it from your email app, or ';
  const retry=document.createElement('a');retry.href=url;retry.textContent='open the draft again';status.append(msg,retry);
  celebrateInquiry(form,url);
 });
}

if(host){
 const reduce=matchMedia('(prefers-reduced-motion: reduce)');
 const map=document.querySelector('.host-route-map'),svg=map.querySelector('svg'),motion=document.getElementById('host-motion');
 const steps=[...document.querySelectorAll('[data-host-step]')],stops=[...document.querySelectorAll('.host-stop')];
 const film=document.getElementById('host-recap'),sound=document.getElementById('host-sound'),status=document.getElementById('host-video-status');
 let paused=reduce.matches,frame=0,selected=-1;
 function motionState(){document.querySelector('.host-map-panel').classList.toggle('host-motion-paused',paused);if(paused)svg.pauseAnimations();else svg.unpauseAnimations();motion.textContent=paused?'Play motion ▶':'Pause motion Ⅱ';motion.setAttribute('aria-pressed',String(paused));}
 motion.onclick=()=>{paused=!paused;motionState();};motionState();
 function activate(index){
  if(selected===index)return;selected=index;
  steps.forEach((step,i)=>step.classList.toggle('is-active',i===index));
  stops.forEach((stop,i)=>{if(i===index)stop.setAttribute('aria-current','step');else stop.removeAttribute('aria-current');});
  map.style.setProperty('--host-progress',String([.03,.34,.67,1][index]));
  document.getElementById('host-current-count').textContent='0'+(index+1)+' / 04';document.getElementById('host-current-title').textContent=hostSteps[index].short;
 }
 document.querySelectorAll('[data-host-go]').forEach(button=>button.onclick=()=>{const n=Number(button.dataset.hostGo);activate(n);steps[n].scrollIntoView({behavior:reduce.matches?'instant':'smooth',block:'center'});});
 function update(){frame=0;let closest=0,distance=Infinity;steps.forEach((step,i)=>{const box=step.getBoundingClientRect(),d=Math.abs(box.top+Math.min(box.height/2,180)-innerHeight*.5);if(d<distance){distance=d;closest=i;}});activate(closest);}
 function onScroll(){if(!frame)frame=requestAnimationFrame(update);}
 window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',onScroll);update();

 if(reduce.matches){film.autoplay=false;film.pause();}else film.play().catch(()=>{status.textContent='Press play to start the film.';});
 sound.onclick=()=>{film.muted=!film.muted;if(film.paused)film.play().catch(()=>{status.textContent='Use the video controls to start playback.';});};
 const volume=()=>{sound.textContent=film.muted?'Play with sound ♫':'Mute sound ♫';};film.addEventListener('volumechange',volume);
 film.addEventListener('playing',()=>{status.textContent='';});
 function preference(){paused=reduce.matches;motionState();if(paused)film.pause();}
 reduce.addEventListener('change',preference);
 window.TWT_HOST_CLEANUP=()=>{window.removeEventListener('scroll',onScroll);window.removeEventListener('resize',onScroll);cancelAnimationFrame(frame);reduce.removeEventListener('change',preference);film.pause();};
}


if(host){
 const form=document.getElementById('host-inquiry-form'),details=document.getElementById('host-questionnaire');
 document.querySelectorAll('[data-open-host-form]').forEach(link=>link.addEventListener('click',()=>{details.open=true;}));
 form.addEventListener('invalid',event=>{let parent=event.target.parentElement;while(parent&&parent!==form){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}},true);
 const dateType=document.getElementById('host-date-type');
 dateType.addEventListener('change',()=>{document.querySelectorAll('[data-date-mode]').forEach(panel=>{const active=panel.dataset.dateMode===dateType.value;panel.hidden=!active;panel.querySelectorAll('input,textarea').forEach(input=>input.disabled=!active);});});
 document.querySelectorAll('[data-date-mode] input,[data-date-mode] textarea').forEach(input=>input.disabled=true);
 form.elements.startDate.addEventListener('change',()=>{form.elements.endDate.min=form.elements.startDate.value;});
 const goals=[...form.querySelectorAll('input[name="goals"]')];
 function syncRequiredGoals(){
  const selected=goals.filter(box=>box.checked).map(box=>box.value);
  goals[0].required=selected.length===0;
  goals[0].setCustomValidity(selected.length?'':'Please select at least one goal.');
  document.getElementById('host-goals-selection').textContent=selected.length?selected.join(' · '):'Choose your goals';
 }
 goals.forEach(input=>input.addEventListener('change',syncRequiredGoals));syncRequiredGoals();
 form.addEventListener('submit',event=>{
  event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);
  const dates=data.get('dateType')==='month'?(data.get('month')||'Month/year to be confirmed'):data.get('dateType')==='estimated'?(data.get('estimatedDates')||'Estimated dates to be confirmed'):data.get('dateType')==='exact'?((data.get('startDate')||'Start date to be confirmed')+' to '+(data.get('endDate')||'End date to be confirmed')):'Not sure yet';
  const values=[['Name',data.get('name')],['Email',data.get('email')],['Phone',data.get('phone')],['Brand / business',data.get('brand')],['Instagram',data.get('instagram')],['Website',data.get('website')],['Destination — first choice',data.get('destination1')],['Destination — second choice',data.get('destination2')],['Destination — third choice',data.get('destination3')],['Theme',data.get('theme')],['Occasion',data.get('occasion')],['Dates',dates],['Price point per person excluding flights',data.get('budget')],['Goal of retreat',data.getAll('goals').join(', ')],['Brain dump',data.get('vision')]];
  const body='Hi T World Tours,\n\nI’d love to host a trip with my community.\n\n'+values.map(([label,value])=>label+': '+(value||'To be discussed')).join('\n\n');
  const url='mailto:'+C.email+'?subject='+encodeURIComponent('Host a Trip inquiry — '+(data.get('brand')||data.get('name')))+'&body='+encodeURIComponent(body);
  const status=document.getElementById('host-inquiry-status');status.replaceChildren();status.append(document.createTextNode('Your draft is ready. Review and send it in your email app. '));const link=document.createElement('a');link.href=url;link.textContent='Open email draft again';status.append(link);celebrateInquiry(form,url);
 });
}

// Celebrate a valid preview submission without claiming that a code was delivered.
function celebrateSignup(button){
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 document.querySelectorAll('.signup-confetti').forEach(el=>el.remove());
 const box=button.getBoundingClientRect(),burst=document.createElement('div');
 burst.className='signup-confetti';burst.setAttribute('aria-hidden','true');document.body.append(burst);
 const colors=['#98c4c6','#a9c1a9','#c6a469','#f6ecda','#91917f'];
 for(let i=0;i<68;i++){
  const piece=document.createElement('i');const angle=Math.PI+(i/67)*Math.PI;
  const reach=100+Math.random()*260;piece.style.left=(box.left+box.width/2)+'px';piece.style.top=(box.top+box.height/2)+'px';
  piece.style.background=colors[i%colors.length];piece.style.borderRadius=i%3===0?'50%':'1px';
  piece.style.setProperty('--dx',(Math.cos(angle)*reach)+'px');piece.style.setProperty('--dy',(Math.sin(angle)*reach)+'px');
  piece.style.setProperty('--spin',((Math.random()-.5)*1400)+'deg');piece.style.animationDelay=(Math.random()*80)+'ms';burst.append(piece);
 }
 setTimeout(()=>burst.remove(),1900);
}

function celebrateInquiry(form,url){
 const button=form.querySelector('button[type="submit"]');
 clearTimeout(form.twtInquiryTimer);
 celebrateSignup(button);
 if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){location.href=url;return;}
 form.twtInquiryTimer=setTimeout(()=>{location.href=url;},750);
}
